def check_n():
    solutions = []
    for n in range(1000):
        f_n = n**3 + 4*n**2 + 6*n + 4
        # Check if f_n only has prime factors 2 and 5
        # and if it divides 20**(n+1)
        temp = f_n
        is_valid_factors = True
        if temp == 0:
            is_valid_factors = False
        else:
            while temp % 2 == 0:
                temp //= 2
            while temp % 5 == 0:
                temp //= 5
            if temp != 1:
                is_valid_factors = False

        if is_valid_factors:
            # Now check if f_n divides 20**(n+1)
            # Actually, if it only has factors 2 and 5, we just need to check the exponents.
            # But let's just do the direct divisibility.
            if (20**(n+1)) % f_n == 0:
                solutions.append(n)
    return solutions

